// Extract intent from AI response
const aiResponse = $input.first().json;
let intent = 'chat';
let target = null;
let content = null;
let query = null;

try {
  let responseText = '';

  // Get the AI response text - handle multiple possible structures
  if (aiResponse.output?.[0]?.content?.[0]?.text) {
    responseText = aiResponse.output[0].content[0].text;
  } else if (aiResponse.output?.content?.[0]?.text) {
    responseText = aiResponse.output.content[0].text;
  } else if (aiResponse.content) {
    // Direct content field (common with Ollama)
    responseText = aiResponse.content;
  } else if (aiResponse.text) {
    responseText = aiResponse.text;
  }

  responseText = responseText.trim();

  // Strip markdown code fences if present
  // Handles: ```json ... ``` or ``` ... ```
  const codeBlockMatch = responseText.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  if (codeBlockMatch) {
    responseText = codeBlockMatch[1].trim();
  }

  // Try to parse as JSON
  if (responseText.startsWith('{')) {
    const parsed = JSON.parse(responseText);
    // Support both 'intent' (new) and 'category' (old) for backwards compatibility
    intent = (parsed.intent || parsed.category || 'chat').toLowerCase();
    target = parsed.target || null;
    content = parsed.content || null;
    query = parsed.query || null;
  } else {
    // Fallback: treat as plain category word
    intent = responseText.toLowerCase();
  }

} catch (e) {
  // Log error for debugging
  console.log('Parse error:', e.message);
  intent = 'chat';
}

// Get original message from Prepare_Input
const prepareInput = $('Prepare_Input').first().json;

return {
  json: {
    intent: intent,
    target: target,
    content: content,
    query: query,
    message: prepareInput.message,
    sender: prepareInput.sender
  }
};

// Extract chat response
const response = $input.first().json;
const content = response.choices?.[0]?.message?.content || "I'm not sure how to help with that.";

return [{
  json: {
    reply: content
  }
}];

return {
  body: $('Webhook_SimpleX_In').first().json.body
};

const target = $json.target || '';
const contentText = $json.content || '';

// Only combine if both exist, otherwise use whichever is available
let message;
if (target && contentText) {
  message = `${target}: ${contentText}`;
} else {
  message = target || contentText || $json.message || '';
}

return {
  message: message,
  content: contentText,
  target: target,
  original_text: message,
  sender: $json.sender
};

return {
  message: $('Prepare_Input').first().json.message,
  sender: $('Prepare_Input').first().json.sender
};

return {
  message: $('Prepare_Input').first().json.message,
  sender: $('Prepare_Input').first().json.sender
};

// Use message, not query - the AI strips too much
let query = $json.message;

// Remove delete-specific command words
query = query.replace(/^(delete|remove)\s+/i, '');
query = query.replace(/\s*(entry|note|capture)\s*/i, ' ');
query = query.replace(/\s*(about|from)\s*/i, ' ');

// Remove database specifiers like "in ideas", "from people", "in projects"
query = query.replace(/\s+(in|from)\s+(ideas|people|projects|admin|vault|obsidian)\s*$/i, '');

// Clean up extra spaces
query = query.replace(/\s+/g, ' ').trim();

return {
  query: query,
  sender: $json.sender
};

const results = $input.all();
const sender = $('Prepare_Delete_Call').first().json.sender;
const query = $('Prepare_Delete_Call').first().json.query;

if (!results || results.length === 0 || !results[0].json.results) {
  return {
    json: {
      reply: `❌ No matches found for "${query}".`,
      has_match: false,
      multiple: false,
      matches: [],
      sender: sender
    }
  };
}

const searchResults = results[0].json.results;

if (searchResults.length === 0) {
  return {
    json: {
      reply: `❌ No matches found for "${query}".`,
      has_match: false,
      multiple: false,
      matches: [],
      sender: sender
    }
  };
}

// Single match - can proceed directly
if (searchResults.length === 1) {
  const match = searchResults[0];
  return {
    json: {
      reply: `🗑️ Found: "${match.name}" in ${match.database}\n\nReply 'yes' to delete, or 'cancel'.`,
      has_match: true,
      multiple: false,
      matches: [{
        id: match.id,
        database: match.database,
        name: match.name
      }],
      pending_id: match.id,
      pending_database: match.database,
      pending_name: match.name,
      sender: sender
    }
  };
}

// Multiple matches - need selection
const matches = searchResults.map((match, index) => {
  // Get emoji for database type
  const dbEmoji = {
    'people': '👤',
    'projects': '📁',
    'ideas': '💡',
    'admin': '📋',
    'inbox_log': '📥'
  }[match.database] || '📄';

  // Format timestamp if available
  let timestamp = '';
  if (match.context && match.context.includes('20')) {
    const dateMatch = match.context.match(/(\d{2}\/\d{2}\s+\d{2}:\d{2})/);
    if (dateMatch) timestamp = ` (${dateMatch[1]})`;
  }

  return {
    id: match.id,
    database: match.database,
    name: match.name,
    displayName: `${dbEmoji} "${match.name}" in ${match.database}${timestamp}`
  };
});

// Build reply message
let reply = `🔍 Found ${matches.length} matches:\n\n`;
matches.forEach((match, index) => {
  reply += `${index + 1}. ${match.displayName}\n`;
});
reply += `\nReply with number (1-${matches.length}) to delete, or 'cancel'.`;

return {
  json: {
    reply: reply,
    has_match: true,
    multiple: true,
    matches: matches.map(m => ({
      id: m.id,
      database: m.database,
      name: m.name
    })),
    sender: sender
  }
};

return {
  sender: $json.sender,
  message: $json.message
};

const result = $input.first().json;

if (result.success) {
  return {
    reply: `✅ Deleted: "${result.deleted_name}"`
  };
} else {
  return {
    reply: `❌ Failed to delete. Please try again.`
  };
}

return {
  sender: $json.sender
};

const response = $input.first().json;
const sender = $('Handle_Confirm').first().json.sender;

// Check if we got an error (404 or 410)
if (response.detail) {
  if (response.detail === "Pending delete expired") {
    return {
      action: 'expired',
      reply: `⏰ Delete request expired. Please try again.`
    };
  }
  return {
    action: 'none', 
    reply: `❓ Nothing to confirm. Use 'delete [entry]' first.`
  };
}

return {
  action: 'delete',
  id: response.id,
  database: response.database,
  name: response.name,
  sender: sender
};

return {
  reply: `🚫 Cancelled. Nothing was deleted.`
};

const confirmation = $('Format_Delete_Confirmation').first().json;
return {
  reply: confirmation.reply
};

const deleteResult = $('Format_Delete_Result').first().json;
return {
  reply: deleteResult.reply
};

/**
 * Pre_Route - Fast Calendar, Task & Command Detection
 * 
 * Workflow: SimpleX_SecondBrain_Router
 * Node: Pre route calendar
 * 
 * Purpose: Detects obvious requests without using AI classification.
 *          Improves response time for common operations.
 *          Routes tasks directly to tasks workflow.
 *          Routes calendar operations directly to calendar workflow.
 *          Passes special commands (fix, confirm, cancel) to AI classifier.
 * 
 * Input: $json.message or $json.query
 * Output: intent, calendarAction (if calendar), skipAI flag, routedBy indicator
 * 
 * Last updated: 2026-01-26
 */

const message = ($json.message || $json.query || '').toLowerCase();

// ============================================================================
// SPECIAL COMMANDS - Must check FIRST before any other detection
// These need AI classification for proper handling
// ============================================================================
const isFixCommand = /^fix[:\s]/i.test(message.trim());
const isConfirmCommand = /^(yes|yep|yeah|confirm|do it|go ahead|ok|okay)$/i.test(message.trim());
const isCancelCommand = /^(no|nope|cancel|nevermind|never mind|stop)$/i.test(message.trim());
const isNumericSelection = /^\d+$/.test(message.trim());

if (isFixCommand || isConfirmCommand || isCancelCommand || isNumericSelection) {
  return {
    json: {
      ...$json,
      skipAI: false
    }
  };
}

// ============================================================================
// TASK DETECTION - Route directly to tasks workflow
// Tasks take priority over calendar - if user says "task", they mean task
// ============================================================================
const isTaskRequest = /\b(task|todo|to-do|to do)\b/.test(message);
if (isTaskRequest) {
  return {
    json: {
      ...$json,
      intent: 'tasks',
      skipAI: true,
      routedBy: 'pre-route-tasks'
    }
  };
}

// ============================================================================
// DATE/TIME PATTERNS - Indicators that suggest calendar context
// ============================================================================
const datePatterns = [
  /\b(today|tonight|tomorrow|yesterday)\b/,
  /\b(mon|monday|tue|tues|tuesday|wed|wednesday|thu|thur|thurs|thursday|fri|friday|sat|saturday|sun|sunday)\b/i,
  /\b(next|this|last)\s+(week|month|mon|monday|tue|tues|tuesday|wed|wednesday|thu|thur|thurs|thursday|fri|friday|sat|saturday|sun|sunday)\b/i,
  /\b\d{1,2}(st|nd|rd|th)?\s*(of\s+)?(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)/i,
  /\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)\s+\d{1,2}(st|nd|rd|th)?\b/i,
  /\b(the\s+)?\d{1,2}(st|nd|rd|th)\b/,  // "the 22nd", "on the 5th"
  /\b\d{1,2}(:\d{2})?\s*(am|pm)\b/,      // "3pm", "15:00"
  /\bin\s+\d+\s+days?\b/,                 // "in 3 days"
  /\b\d+\s+days?\s+(ago|from now)\b/,     // "2 days ago"
  /\bday\s+(after|before)\s+(tomorrow|yesterday)\b/,
  /\b(for\s+)?(the\s+)?week\b/           // "the week", "this week"
];

// ============================================================================
// CALENDAR ACTION WORDS
// ============================================================================
const calendarQueryWords = [
  'what\'s on', 'whats on', 'schedule', 'calendar', 
  'busy', 'free', 'do i have', 'am i', 
  'show my', 'list my', 'check my'
];

const calendarAddWords = [
  'add', 'create', 'schedule', 'book', 
  'set up', 'put in', 'new event', 'new meeting', 'new appointment'
];

const calendarDeleteWords = [
  'cancel', 'delete', 'remove', 'drop', 'clear', 'wipe'
];

// ============================================================================
// PATTERN DETECTION
// ============================================================================
const hasDateIndicator = datePatterns.some(pattern => pattern.test(message));
const hasQueryWord = calendarQueryWords.some(word => message.includes(word));
const hasAddWord = calendarAddWords.some(word => message.includes(word));
const hasDeleteWord = calendarDeleteWords.some(word => message.includes(word));

// Time and event patterns for implicit calendar adds
const hasTimePattern = /\b\d{1,2}(:\d{2})?\s*(am|pm)\b/.test(message) || /\bat\s+(noon|midnight)\b/.test(message);
const hasEventWord = /\b(meeting|appointment|call|lunch|dinner|breakfast|event|shift)\b/.test(message);

// ============================================================================
// CALENDAR ACTION CLASSIFICATION
// ============================================================================
let isCalendar = false;
let calendarAction = null;

// Query: calendar query words OR "what" + date indicator
if (hasQueryWord || (message.includes('what') && hasDateIndicator)) {
  isCalendar = true;
  calendarAction = 'query';
}

// Add: date/time indicator + add words
if (hasAddWord && hasDateIndicator) {
  isCalendar = true;
  calendarAction = 'add';
}

// Delete: delete words + date indicator
if (hasDeleteWord && hasDateIndicator) {
  isCalendar = true;
  calendarAction = 'delete';
}

// Implicit add: time + event word + date, without delete/query words
// e.g., "meeting at 3pm tomorrow", "lunch with Bob at noon"
if (hasTimePattern && hasEventWord && hasDateIndicator && !hasDeleteWord && !hasQueryWord) {
  isCalendar = true;
  calendarAction = 'add';
}

// ============================================================================
// RETURN RESULT
// ============================================================================
if (isCalendar) {
  return {
    json: {
      ...$json,
      intent: 'calendar',
      calendarAction: calendarAction,
      skipAI: true,
      routedBy: 'pre-route-calendar'
    }
  };
}

// Not a clear pattern - let AI classify
return {
  json: {
    ...$json,
    skipAI: false
  }
};

// Extract category from the fix command
const message = $json.message || '';
let category = $json.category;

// If category not set, parse from message
if (!category) {
  const match = message.toLowerCase().match(/fix[:\s]+(\w+)/);
  if (match) {
    const raw = match[1];
    // Normalize category names
    const categoryMap = {
      'people': 'people', 'person': 'people',
      'project': 'projects', 'projects': 'projects',
      'idea': 'ideas', 'ideas': 'ideas',
      'admin': 'admin', 'task': 'admin', 'tasks': 'admin'
    };
    category = categoryMap[raw] || raw;
  }
}

// Extract optional name override
let name = $json.name;
if (!name) {
  const nameMatch = message.match(/call it\s+(.+)/i);
  if (nameMatch) {
    name = nameMatch[1].trim();
  }
}

return {
  json: {
    ...$json,
    category: category,
    name: name || null
  }
};

const message = $json.message || $json.query || '';
const number = parseInt(message.trim(), 10);

return {
  json: {
    selection: number,
    sender: $json.sender
  }
};

const input = $input.first().json;

// Data is nested under 'body' when using Response option
const data = input.body || input;

// Success case
if (data.success) {
  return { json: { reply: data.message } };
}

// Error case - extract from error response
const detail = data.detail || input.errorDescription || 'Selection failed';

if (detail.includes('Invalid selection')) {
  return { json: { reply: `❌ ${detail}` } };
}

if (detail.includes('expired')) {
  return { json: { reply: '⏰ Selection expired. Please start again.' } };
}

if (detail.includes('No pending')) {
  return { json: { reply: '❌ No pending selection. Start a new delete request.' } };
}

return { json: { reply: `❌ ${detail}` } };

// Pass_Selection_Reply (Code node)
const result = $('Format_Selection_Result').first().json;

return {
  json: {
    reply: result.reply,
    contactId: $('Parse_Selection').first().json.sender
  }
};

